"import * as THREE from 'three';
import { getConcreteTexture, getFloorTileTexture, getRustMetalTexture } from '../textures.js';

export function makeConcreteMaterial(tint = 0x7c7e82) {
  const tex = getConcreteTexture(2, 1.4);
  return new THREE.MeshStandardMaterial({
    map: tex,
    bumpMap: tex,
    bumpScale: 0.035,
    color: tint,
    roughness: 0.92,
    metalness: 0.08
  });
}

export function makeRustMaterial(hex = 0x5c463c, roughness = 0.72, metalness = 0.62) {
  const tex = getRustMetalTexture();
  return new THREE.MeshStandardMaterial({
    map: tex,
    bumpMap: tex,
    bumpScale: 0.025,
    color: hex,
    roughness,
    metalness
  });
}

export function makeBrassMaterial(hex = 0x9c7b49) {
  const tex = getRustMetalTexture('#473924');
  return new THREE.MeshStandardMaterial({
    map: tex,
    bumpMap: tex,
    bumpScale: 0.015,
    color: hex,
    roughness: 0.42,
    metalness: 0.82
  });
}

// Registra un gruppo/mesh come bersaglio interattivo per il raycasting
export function tagInteractive(object, config) {
  const highlightMeshes = [];
  object.traverse((child) => {
    if (child.isMesh && !child.userData.noHighlight) {
      child.material = child.material.clone();
      child.userData.baseEmissive = child.material.emissive
        ? child.material.emissive.clone()
        : new THREE.Color(0x000000);
      child.userData.baseEmissiveIntensity = child.material.emissiveIntensity ?? 1;
      highlightMeshes.push(child);
    }
  });

  object.userData.interactive = {
    ...config,
    highlightMeshes
  };
  return object;
}

